    // Determine speed
    if (isDeleting) {
      setDelta(60); // Faster, constant delete speed
    } else {
      setDelta(150); // Constant typing speed
    }

    // Phase transitions
    if (!isDeleting && updatedText === fullText) {
      setIsDeleting(true);
      setDelta(2000); // Pause at end of word
    } else if (isDeleting && updatedText === '') {
      setIsDeleting(false);
      setLoopNum(loopNum + 1);
      setDelta(500); // Pause before next word
